with c as (select id from public.academy_courses where id='meteorology-forecasting-foundations'),
ch as (insert into public.academy_chapters(course_id,title,description,sort_order,published) select id,'الأرصاد التخصصية والتطبيقات القطاعية','تطبيقات الأرصاد في الزراعة والبحر والطيران والمدن وجودة الهواء والطاقة والنقل والبيئة الجبلية والأنظمة المدارية.',18,false from c on conflict(course_id,title) do update set description=excluded.description returning id),
u1 as (insert into public.academy_units(chapter_id,title,sort_order,published) select id,'الأرصاد الزراعية والبيئية',1,false from ch on conflict(chapter_id,title) do update set sort_order=excluded.sort_order returning id),
u2 as (insert into public.academy_units(chapter_id,title,sort_order,published) select id,'الأرصاد البحرية والجوية المتخصصة',2,false from ch on conflict(chapter_id,title) do update set sort_order=excluded.sort_order returning id),
u3 as (insert into public.academy_units(chapter_id,title,sort_order,published) select id,'الأرصاد الحضرية وجودة الهواء والطاقة',3,false from ch on conflict(chapter_id,title) do update set sort_order=excluded.sort_order returning id),
u4 as (insert into public.academy_units(chapter_id,title,sort_order,published) select id,'الطقس المتخصص والمخاطر الإقليمية',4,false from ch on conflict(chapter_id,title) do update set sort_order=excluded.sort_order returning id),
d(slug,title,summary,content,ord,mins,objectives,unit) as (values ('agrometeorology-crop-weather-relations','الأرصاد الزراعية وعلاقة الطقس بالمحاصيل','تأثير الحرارة والهطول والرطوبة والرياح في نمو المحاصيل والإجهاد الزراعي.','{"blocks":[{"type":"text","text":"تدرس الأرصاد الزراعية التفاعل بين الطقس والمناخ والتربة والنبات وإدارة المحاصيل."},{"type":"text","text":"تؤثر درجة الحرارة في الإنبات والنمو والإزهار وتكوين الثمار، وتختلف الحدود المناسبة بحسب المحصول والمرحلة."},{"type":"text","text":"تستخدم درجات الحرارة الأساسية والعليا في حساب الوحدات الحرارية أو درجات النمو المتراكمة وفق منهجية المحصول."},{"type":"text","text":"قد يؤدي الصقيع إلى أضرار زراعية عندما تنخفض حرارة الأنسجة النباتية إلى مستويات حساسة، ويختلف ذلك حسب النوع والمرحلة."},{"type":"text","text":"يؤثر الهطول في مخزون رطوبة التربة، لكن كفاءة الاستفادة منه تعتمد على الشدة والتوزيع والتسرب والجريان."},{"type":"text","text":"تؤثر الرطوبة والبلل الورقي ومدة ابتلال النبات في ظروف تطور بعض الأمراض النباتية."},{"type":"text","text":"تزيد الرياح التبخر وقد تسبب رقاد بعض المحاصيل أو تؤثر في عمليات التلقيح والرش."},{"type":"text","text":"يساعد التبخر-النتح المرجعي ET0 ومعامل المحصول Kc في تقدير الاحتياج المائي تحت افتراضات مناسبة."},{"type":"text","text":"تستخدم محطات الأرصاد الزراعية لقياس الحرارة والرطوبة والرياح والإشعاع والهطول قرب الحقول."},{"type":"text","text":"تحتاج التوصيات الزراعية إلى دمج التوقع الجوي مع نوع المحصول والتربة ومرحلة النمو وإدارة الري."},{"type":"text","text":"مثال: توقع موجة حر أثناء الإزهار يستدعي تقييم حساسية المحصول وتوفر المياه وتوقيت المرحلة الزراعية."},{"type":"callout","text":"خلاصة: الخدمة الزراعية الفعالة تحول بيانات الطقس إلى معلومات مرتبطة بمرحلة المحصول واحتياجاته."}]}',1060,55,'["شرح عناصر المناخ الزراعي","فهم درجات الحرارة الفعالة","ربط الطقس بمراحل نمو النبات"]','الأرصاد القطاعية'),
('marine-meteorology-and-ocean-atmosphere','الأرصاد البحرية والتفاعل بين المحيط والغلاف الجوي','الرياح البحرية والأمواج والضغط والتدفقات الحرارية والرطوبة فوق المحيط.','{"blocks":[{"type":"text","text":"تدرس الأرصاد البحرية حالة الغلاف الجوي فوق البحار وتأثيرها في الملاحة والسواحل والأنشطة البحرية."},{"type":"text","text":"تختلف بيئة الرصد البحري عن اليابسة بسبب السعة الحرارية الكبيرة للماء وخشونة السطح المتغيرة."},{"type":"text","text":"تؤثر سرعة الرياح ومدتها ومسافة هبوبها فوق الماء في نمو الأمواج وحالتها."},{"type":"text","text":"يسهم فرق حرارة سطح البحر والهواء في تحديد اتجاه وشدة التدفقات الحرارية والرطوبية."},{"type":"text","text":"قد تؤثر التيارات البحرية وارتفاع حرارة سطح البحر في استقرار الطبقة السفلى وتطور السحب والضباب."},{"type":"text","text":"تستخدم العوامات والسفن والمنصات البحرية والأقمار الصناعية لجمع بيانات الضغط والرياح والحرارة والرطوبة والأمواج."},{"type":"text","text":"تتطلب قياسات الرياح البحرية تصحيح أثر حركة السفينة أو المنصة وارتفاع الحساس والتعرض الهوائي."},{"type":"text","text":"تستخدم خرائط الضغط والرياح والأمواج لتحديد مناطق الطقس البحري المضطرب ومسارات الأنظمة الجوية."},{"type":"text","text":"قد تتكون سحب منخفضة وضباب بحري عند انتقال هواء رطب فوق مياه أبرد أو عند توافر شروط الإشباع."},{"type":"text","text":"تحتاج المنتجات البحرية إلى تحديد الفترة ومصدر القياس ووحدات ارتفاع الموج وفترته واتجاهه."},{"type":"text","text":"مثال: مرور هواء دافئ رطب فوق تيار بحري أبرد قد يهيئ ظروف ضباب انتقالي إذا تحقق الإشباع قرب السطح."},{"type":"callout","text":"خلاصة: الطقس البحري نتاج تفاعل مستمر بين الغلاف الجوي وسطح المحيط وحركة المياه."}]}',1070,55,'["شرح عناصر الرصد البحري","فهم التبادل الحراري والرطوبي","تحليل الطقس فوق البحار"]','الأرصاد القطاعية'),
('aviation-meteorology-and-flight-weather','أرصاد الطيران والظواهر المؤثرة في الملاحة الجوية','الرؤية والسحب والاضطراب والجليد والرياح والمنتجات الجوية للمطارات.','{"blocks":[{"type":"text","text":"تقدم أرصاد الطيران معلومات عن الظروف الجوية التي تؤثر في الإقلاع والهبوط والطيران على المسارات."},{"type":"text","text":"تعد الرؤية ومدى السحب وقاعدة السحب والرياح والضغط من العناصر المهمة في تقارير المطارات."},{"type":"text","text":"يعرض METAR حالة الرصد الحالية، بينما يقدم TAF توقعاً جوياً للمطار خلال فترة صلاحية محددة."},{"type":"text","text":"قد تؤثر السحب المنخفضة والضباب والهطول في الرؤية والارتفاع المتاح للمناورة وفق إجراءات الطيران."},{"type":"text","text":"قد ينتج الجليد على الطائرات عند مرورها في سحب تحتوي قطرات فائقة التبريد، ويعتمد الخطر على نوع القطيرات والحرارة والمدة."},{"type":"text","text":"ينشأ الاضطراب الجوي من موجات الجاذبية والقص والتيارات النفاثة والحمل الحراري والتضاريس."},{"type":"text","text":"قد تتسبب العواصف الرعدية في اضطراب شديد وهطول وبرد وبرق وتغيرات سريعة في الرياح."},{"type":"text","text":"يؤثر قص الرياح قرب المدرج في تغير سرعة الرياح النسبية للطائرة خلال مراحل حرجة من الطيران."},{"type":"text","text":"تستخدم نشرات SIGMET وAIRMET وغيرها وفق الأنظمة الوطنية والدولية لإبلاغ معلومات الطقس المهمة للطيران."},{"type":"text","text":"يجب تفسير المنتجات وفق التعاريف التشغيلية المعتمدة وعدم استبدالها بتقدير غير رسمي."},{"type":"text","text":"مثال: توقع ضباب قرب الفجر يحتاج متابعة الرؤية وقاعدة السحب والرياح وفرق الحرارة عن نقطة الندى."},{"type":"callout","text":"خلاصة: أرصاد الطيران تخصص تطبيقي يتطلب دقة التوقيت والموقع والمصطلحات التشغيلية."}]}',1080,55,'["شرح عناصر الطقس المهمة للطيران","قراءة تقارير METAR وTAF","التعرف إلى مخاطر الطيران الجوية"]','الأرصاد القطاعية'),
('urban-meteorology-heat-islands','الأرصاد الحضرية والجزر الحرارية','تأثير العمران والمواد والأسطح والتهوية في المناخ المحلي للمدن.','{"blocks":[{"type":"text","text":"تدرس الأرصاد الحضرية تأثير المباني والطرق والمواد والغطاء النباتي في الطقس والمناخ المحلي للمدن."},{"type":"text","text":"تنتج الجزيرة الحرارية الحضرية من اختلاف تخزين الطاقة والإشعاع والتهوية والحرارة البشرية بين المدينة ومحيطها."},{"type":"text","text":"تمتص المواد العمرانية الطاقة خلال النهار وتطلق جزءاً منها ليلاً، ما قد يرفع حرارة الهواء والأسطح."},{"type":"text","text":"تقلل الأسطح غير النفاذة والغطاء النباتي المحدود من التبخر-النتح والتبريد التبخري."},{"type":"text","text":"تؤثر هندسة الشوارع وارتفاع المباني في الظلال وتدفق الهواء واحتجاز الحرارة والملوثات."},{"type":"text","text":"تتغير شدة الجزيرة الحرارية مكانياً وزمانياً، وقد تختلف بين وسط المدينة والضواحي والحدائق والمناطق الصناعية."},{"type":"text","text":"تؤثر نسائم الوادي والبحر والرياح الإقليمية في تهوية المدينة ونقل الحرارة والملوثات."},{"type":"text","text":"تستخدم محطات حضرية وشبكات حساسات متنقلة وصور حرارية وبيانات الأقمار لدراسة التباين المحلي."},{"type":"text","text":"يجب التمييز بين حرارة سطح الأرض المستشعرة بالأقمار وحرارة الهواء المقاسة في المحطات."},{"type":"text","text":"تساعد المساحات الخضراء والظل والأسطح ذات الانعكاسية المناسبة على تخفيف بعض مظاهر الإجهاد الحراري الحضري وفق التصميم والمناخ المحلي."},{"type":"text","text":"مثال: قد تسجل منطقة عمرانية كثيفة حرارة ليلية أعلى من حديقة مجاورة بسبب اختلاف التخزين الحراري والتهوية."},{"type":"callout","text":"خلاصة: فهم مناخ المدن يتطلب قياسات دقيقة وتحليلاً مكانياً وربط الطقس بتخطيط البيئة المبنية."}]}',1090,55,'["شرح الجزيرة الحرارية الحضرية","فهم ميزانية الطاقة الحضرية","تحليل التهوية والتباين المكاني"]','الأرصاد القطاعية'),
('air-quality-and-atmospheric-dispersion','جودة الهواء وانتقال الملوثات في الغلاف الجوي','تأثير الرياح والاستقرار والخلط والارتفاعات الانعكاسية في تراكيز الملوثات.','{"blocks":[{"type":"text","text":"تتأثر تراكيز الملوثات بمعدلات الانبعاث والنقل الأفقي والخلط الرأسي والتحولات الكيميائية والترسيب."},{"type":"text","text":"تساعد الرياح على نقل الملوثات وتخفيفها أو توجيهها نحو مناطق أخرى بحسب المصدر والاتجاه."},{"type":"text","text":"يحد الاستقرار القوي والانقلاب الحراري من الخلط الرأسي وقد يسهم في تراكم بعض الملوثات قرب السطح."},{"type":"text","text":"يزيد ارتفاع طبقة الخلط عادة حجم الهواء المتاح لتخفيف الملوثات، مع بقاء أثر الانبعاثات والنقل قائماً."},{"type":"text","text":"قد يؤدي الحمل الحراري النهاري إلى خلط أعمق ونقل الملوثات إلى طبقات أعلى."},{"type":"text","text":"تؤثر الرطوبة والإشعاع ودرجة الحرارة في التفاعلات الكيميائية وتكوين بعض الملوثات الثانوية."},{"type":"text","text":"تستخدم محطات جودة الهواء لقياس الجسيمات والغازات وفق طرق ومعايير محددة."},{"type":"text","text":"يمثل مؤشر جودة الهواء طريقة تواصل مبسطة، ويعتمد تفسيره على الملوثات وفترات المتوسط والحدود الوطنية أو الدولية."},{"type":"text","text":"تساعد النماذج الكيميائية الجوية على تمثيل الانبعاثات والنقل والتحول والترسيب، وتحتاج بيانات انبعاثات موثوقة."},{"type":"text","text":"يجب التمييز بين تركيز الملوث في موقع المحطة والتعرض الشخصي، إذ يتأثر الأخير بالمكان والوقت والسلوك والبيئة الداخلية."},{"type":"text","text":"مثال: ليلة ساكنة مع انقلاب حراري قد تهيئ لتراكم الملوثات إذا استمرت الانبعاثات ولم يحدث خلط كافٍ."},{"type":"callout","text":"خلاصة: الأرصاد عنصر أساسي في تفسير جودة الهواء لكنها تعمل مع بيانات الانبعاثات والكيمياء والرصد."}]}',1100,55,'["شرح أثر الطقس في جودة الهواء","فهم الخلط والانتقال والتشتت","قراءة مؤشرات جودة الهواء"]','الأرصاد القطاعية'),
('renewable-energy-meteorology','أرصاد الطاقة المتجددة وتقييم الموارد','تقدير موارد الرياح والإشعاع الشمسي والتغيرات الجوية المؤثرة في الإنتاج.','{"blocks":[{"type":"text","text":"تستخدم الأرصاد لتقييم الموارد المتاحة لمشروعات طاقة الرياح والطاقة الشمسية وتقدير تغيرها زمنياً ومكانياً."},{"type":"text","text":"تعتمد طاقة الرياح على توزيع سرعة الرياح مع الارتفاع والتضاريس والخشونة والاستقرار الجوي."},{"type":"text","text":"تحتاج دراسات الرياح إلى قياسات طويلة الأمد وبيانات وصفية عن ارتفاع الحساس ومعايرته وموقعه."},{"type":"text","text":"تتأثر القدرة المستخرجة من الرياح بعلاقة توربين محدد بين سرعة الرياح والقدرة، ولا تكفي السرعة المتوسطة وحدها."},{"type":"text","text":"تستخدم مقاييس البيرانومتر لقياس الإشعاع الشمسي الكلي على سطح، بينما يقيس البيرهيليومتر الإشعاع المباشر وفق هندسة القياس."},{"type":"text","text":"يتأثر الإشعاع الواصل إلى الألواح بالسحب والهباء والغبار وزاوية الشمس والظل ودرجة حرارة الوحدة."},{"type":"text","text":"تساعد بيانات الإشعاع الأفقي الكلي والمباشر والمنتشر في تقييم موارد الطاقة الشمسية."},{"type":"text","text":"تحتاج السلاسل الزمنية إلى تصحيح الجودة والفجوات والتحقق من تمثيلها للموقع قبل تقدير الإنتاج طويل الأمد."},{"type":"text","text":"تستخدم النماذج العددية والتوقعات قصيرة المدى لإدارة الإنتاج والتوازن بين العرض والطلب."},{"type":"text","text":"قد تؤدي العواصف الغبارية أو الثلوج أو السحب السريعة إلى تغيرات حادة في الإنتاج الشمسي."},{"type":"text","text":"مثال: موقع ذو إشعاع سنوي مرتفع قد يواجه إنتاجاً أقل من المتوقع إذا كانت بيانات الغبار أو الظلال أو حرارة الألواح غير ممثلة."},{"type":"callout","text":"خلاصة: تقييم الطاقة المتجددة يحتاج رصداً طويل الأمد وتوقعات تشغيلية وبيانات موثوقة عن الموقع."}]}',1110,55,'["شرح موارد الرياح والطاقة الشمسية","فهم قياسات الإشعاع والرياح","تقييم التغير الزمني للموارد"]','الأرصاد القطاعية'),
('road-weather-and-transport-forecasting','أرصاد الطرق والنقل والتنبؤ بحالة السطح','الحرارة السطحية والصقيع والجليد والضباب والهطول وتأثيرها في النقل.','{"blocks":[{"type":"text","text":"تدرس أرصاد الطرق الظروف الجوية والسطحية التي قد تؤثر في سلامة وكفاءة النقل البري."},{"type":"text","text":"قد تختلف حرارة سطح الطريق عن حرارة الهواء بسبب الإشعاع والمواد والتخزين الحراري والظل."},{"type":"text","text":"يتشكل الصقيع عندما يصل سطح بارد إلى ظروف تسمح بترسب الجليد أو تجمد الرطوبة عليه."},{"type":"text","text":"قد يتكون الجليد الأسود عندما تتجمد طبقة رقيقة من الماء على سطح الطريق وتكون صعبة الرؤية."},{"type":"text","text":"تؤثر درجات الحرارة القريبة من الصفر والهطول ونقطة الندى والرياح والغطاء السحابي في احتمالات الجليد."},{"type":"text","text":"يؤدي الضباب والهطول الشديد والثلوج إلى خفض الرؤية أو تغيير خصائص الاحتكاك على الطرق."},{"type":"text","text":"تستخدم محطات الطقس الطرقية حساسات حرارة السطح والهواء والرطوبة والهطول والرياح."},{"type":"text","text":"تساعد كاميرات الطريق ومجسات حالة السطح وبيانات المرور في تحسين تقييم الظروف الفعلية."},{"type":"text","text":"تحتاج النماذج إلى تمثيل محلي للارتفاع والتضاريس والتعرض والظل، وقد تختلف حالة الطريق خلال مسافات قصيرة."},{"type":"text","text":"يجب أن تميز المنتجات بين توقع حالة الجو وتوقع حالة سطح الطريق، لأن الثاني يحتاج نموذج طاقة سطحية وبيانات إضافية."},{"type":"text","text":"مثال: قد تكون حرارة الهواء فوق الصفر بقليل بينما يبقى جسر مكشوف أبرد من الطريق المحيط بسبب التبريد وفقد الحرارة."},{"type":"callout","text":"خلاصة: أرصاد الطرق تخصص دقيق يدمج الطقس مع خصائص السطح والرصد المحلي."}]}',1120,55,'["تمييز حرارة الهواء عن حرارة الطريق","تحليل الصقيع والجليد السطحي","فهم منتجات الطقس للطرق"]','الأرصاد القطاعية'),
('fire-weather-and-atmospheric-conditions','أرصاد الطقس المرتبطة بحرائق الغطاء النباتي','الحرارة والرطوبة والرياح والجفاف ومؤشرات قابلية انتشار الحرائق.','{"blocks":[{"type":"text","text":"تدرس أرصاد حرائق الغطاء النباتي الظروف الجوية التي تؤثر في قابلية الاشتعال وسرعة انتشار الحريق وشدته المحتملة."},{"type":"text","text":"تؤثر الحرارة والرطوبة النسبية والرياح والهطول السابق في جفاف الوقود النباتي."},{"type":"text","text":"تنخفض رطوبة المواد النباتية الدقيقة بسرعة أكبر من الوقود الخشبي السميك، وتستجيب لتغيرات الطقس."},{"type":"text","text":"تزيد الرياح سرعة انتقال الجبهة النارية وتغير اتجاه انتشارها، كما تؤثر في سلوك عمود الحمل الحراري."},{"type":"text","text":"قد تؤدي الرطوبة المنخفضة والحرارة المرتفعة وفترات الجفاف إلى زيادة قابلية الوقود للاشتعال."},{"type":"text","text":"يساعد الاستقرار وعدم الاستقرار في فهم نمو عمود الدخان والخلط الرأسي ونقل الجسيمات."},{"type":"text","text":"تستخدم مؤشرات مثل Fire Weather Index وفق نظامها ومكوناتها المحلية، ولا تفسر دون معرفة المعايرة والبيئة."},{"type":"text","text":"تتطلب منتجات الطقس للحرائق بيانات عن الغطاء النباتي والتضاريس والرطوبة السابقة إلى جانب الأرصاد."},{"type":"text","text":"قد تنتج عواصف الحمل الحراري تغيرات مفاجئة في اتجاه الرياح وهبات محلية تؤثر في ظروف الحريق."},{"type":"text","text":"تستخدم الأقمار الصناعية لرصد النقاط الساخنة ومساحة الاحتراق والدخان، مع مراعاة زمن المرور والدقة المكانية."},{"type":"text","text":"مثال: يوم حار وجاف وعاصف بعد فترة انقطاع مطري يستدعي رفع مستوى المتابعة وفق نظام الإنذار المحلي."},{"type":"callout","text":"خلاصة: تقييم طقس الحرائق يجمع الأرصاد والغطاء النباتي والتضاريس والرصد الفضائي."}]}',1130,55,'["شرح عناصر طقس الحرائق","فهم رطوبة الوقود النباتي","قراءة مؤشرات الطقس المرتبطة بالحرائق"]','الأرصاد القطاعية'),
('mountain-meteorology-and-orographic-effects','أرصاد الجبال والتأثيرات التضاريسية','الرفع التضاريسي والظل المطري والرياح الجبلية والموجات والاضطرابات.','{"blocks":[{"type":"text","text":"تؤثر الجبال في تدفق الهواء عبر الرفع والتوجيه والحجب وتوليد الموجات الجوية."},{"type":"text","text":"يحدث الرفع التضاريسي عندما يجبر الهواء على الصعود فوق منحدر، وقد يبرد ويتكاثف إذا بلغ الإشباع."},{"type":"text","text":"قد تزيد الأمطار على السفوح المواجهة للرياح الرطبة، بينما ينخفض الهطول على السفوح الواقعة في ظل المطر."},{"type":"text","text":"يعتمد الظل المطري على اتجاه الرياح والاستقرار ومحتوى الرطوبة وارتفاع الحاجز التضاريسي."},{"type":"text","text":"تتكون رياح الوادي والجبل نتيجة فروق التسخين والتبريد المحلية وتغير الكثافة خلال اليوم."},{"type":"text","text":"قد تتسارع الرياح عبر الممرات الجبلية أو حول القمم بسبب توجيه التدفق وتغير الضغط."},{"type":"text","text":"تنشأ موجات الجاذبية الجبلية عندما يعبر الهواء المستقر تضاريس مرتفعة، وقد تمتد آثارها إلى طبقات أعلى."},{"type":"text","text":"قد يؤدي كسر الموجات أو الاضطراب في التدفق إلى قص واضطراب جوي في مناطق معينة."},{"type":"text","text":"تتأثر قياسات المحطات الجبلية بالتعرض والارتفاع والظل والتضاريس المحيطة، ويجب توثيق الموقع بدقة."},{"type":"text","text":"تحتاج النماذج إلى دقة مكانية وتمثيل تضاريسي مناسب، مع إدراك حدودها في الأودية والقمم الضيقة."},{"type":"text","text":"مثال: اختلاف اتجاه الرياح بين سفحين متقابلين قد يؤدي إلى فروق كبيرة في الهطول والحرارة خلال الحالة نفسها."},{"type":"callout","text":"خلاصة: التضاريس ليست مجرد خلفية للخريطة، بل عنصر ديناميكي يغير الطقس محلياً."}]}',1140,55,'["شرح الرفع التضاريسي","فهم الظل المطري","التعرف إلى الرياح والموجات الجبلية"]','الأرصاد القطاعية'),
('tropical-cyclone-structure-and-monitoring','الأعاصير المدارية وبنيتها ومراقبتها','نشأة الأنظمة المدارية وبنية العين والجدار السحابي ومنتجات التتبع.','{"blocks":[{"type":"text","text":"الإعصار المداري نظام منخفض الضغط منظم يستمد جزءاً كبيراً من طاقته من حرارة ورطوبة سطح المحيط."},{"type":"text","text":"تتطلب نشأته عادة مياه سطحية دافئة وعمقاً حرارياً مناسباً ورطوبة متوسطة واستقراراً ديناميكياً وقصاً رأسياً غير مفرط."},{"type":"text","text":"تضم البنية المركزية عيناً قد تكون أهدأ نسبياً، تحيط بها منطقة الجدار العيني ذات الحمل العميق والرياح الأقوى."},{"type":"text","text":"تمتد أشرطة المطر الحلزونية من المركز، وقد تنتج هطولاً غزيراً بعيداً عن منطقة الرياح القصوى."},{"type":"text","text":"تتغير شدة النظام وفق توازن الطاقة والمحيط والقص الجوي والتفاعلات الداخلية."},{"type":"text","text":"تستخدم صور الأقمار المرئية وتحت الحمراء وبخار الماء لتتبع البنية والسحب ودرجة حرارة القمم."},{"type":"text","text":"تسهم قياسات الأقمار والقياسات الجوية والبحرية المتخصصة في تقدير الموقع والضغط والرياح."},{"type":"text","text":"يستخدم التتبع لتحديد المركز والحركة والسرعة والمسار المتوقع، ويجب عرض مخروط المسار بوصفه نطاقاً لعدم اليقين لا حدوداً مؤكدة."},{"type":"text","text":"قد تتجاوز آثار المطر والفيضانات والاندفاع البحري نطاق الرياح القصوى، لذلك لا يختزل الخطر في سرعة الرياح."},{"type":"text","text":"تختلف أسماء وتصنيفات الأنظمة المدارية بين الأحواض، وتعتمد الفئات على معايير تشغيلية محددة."},{"type":"text","text":"مثال: قد يبقى مسار المركز بعيداً عن الساحل بينما تصل أمطار غزيرة وأمواج عالية إلى مناطق واسعة."},{"type":"callout","text":"خلاصة: مراقبة الأعاصير المدارية تجمع الاستشعار الفضائي والقياسات البحرية والنماذج والتحذيرات متعددة الأثر."}]}',1150,55,'["شرح شروط نشأة الأعاصير المدارية","تمييز أجزاء الإعصار","فهم منتجات التتبع والشدة"]','الأرصاد القطاعية'))
insert into public.academy_lessons(course_id,chapter_id,unit_id,slug,title,summary,content,published,sort_order,level,estimated_minutes,learning_objectives,chapter_title,unit_title)
select c.id,ch.id,case d.unit when 'الأرصاد الزراعية والبيئية' then u1.id when 'الأرصاد البحرية والجوية المتخصصة' then u2.id when 'الأرصاد الحضرية وجودة الهواء والطاقة' then u3.id when 'الطقس المتخصص والمخاطر الإقليمية' then u4.id end,d.slug,d.title,d.summary,d.content::jsonb,false,d.ord,'advanced',d.mins,d.objectives::jsonb,'الأرصاد التخصصية والتطبيقات القطاعية',d.unit from d cross join c cross join ch cross join u1 cross join u2 cross join u3 cross join u4
on conflict(course_id,slug) do update set chapter_id=excluded.chapter_id,unit_id=excluded.unit_id,title=excluded.title,summary=excluded.summary,content=excluded.content,published=false,sort_order=excluded.sort_order,level=excluded.level,estimated_minutes=excluded.estimated_minutes,learning_objectives=excluded.learning_objectives,chapter_title=excluded.chapter_title,unit_title=excluded.unit_title;